import{c as d,Q as r,j as a,m as e}from"./chunks/framework.B2dUnTNU.js";const u=JSON.parse('{"title":"Build 42 核心变化总览","description":"","frontmatter":{},"headers":[],"relativePath":"b42/index.md","filePath":"b42/index.md","lastUpdated":1779619065000}'),n={name:"b42/index.md"};function l(o,t,i,s,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="build-42-核心变化总览" tabindex="-1">Build 42 核心变化总览 <a class="header-anchor" href="#build-42-核心变化总览" aria-label="Permalink to &quot;Build 42 核心变化总览&quot;">​</a></h1><p>Build 42（Unstable）是僵尸毁灭工程有史以来<strong>最大的更新</strong>，开发历时三年。核心理念：从文明废墟中劫掠的幸存者，转变为<strong>自给自足的后末日重建者</strong>。</p><p>本文面向 B41 老玩家，只讲<strong>变了什么</strong>，基础机制不重复。</p><hr><h2 id="十大核心变化速览" tabindex="-1">十大核心变化速览 <a class="header-anchor" href="#十大核心变化速览" aria-label="Permalink to &quot;十大核心变化速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>变化</th><th>B41 情况</th><th>B42 情况</th><th>影响</th></tr></thead><tbody><tr><td>1</td><td><strong>锻造系统</strong></td><td>无</td><td>可冶炼铁矿、锻打刀剑、自制钉子</td><td>🔴 全新</td></tr><tr><td>2</td><td><strong>动物/畜牧</strong></td><td>无活物</td><td>8 种动物，可驯养狩猎</td><td>🔴 全新</td></tr><tr><td>3</td><td><strong>光照重做</strong></td><td>方块式亮度</td><td>光线传播/反弹，真正黑暗</td><td>🔴 彻底改变</td></tr><tr><td>4</td><td><strong>肌肉疲劳</strong></td><td>无限挥砍</td><td>重武器造成肌肉拉伤，需轮换</td><td>⚠ 影响战斗</td></tr><tr><td>5</td><td><strong>地下空间</strong></td><td>无</td><td>地下室、避难所、地堡</td><td>🔴 全新</td></tr><tr><td>6</td><td><strong>高楼大厦</strong></td><td>最高 7 层</td><td>最高 32 层摩天楼</td><td>⚠ 影响探索</td></tr><tr><td>7</td><td><strong>农业 2.0</strong></td><td>7 种作物</td><td>50+ 品种、季节系统、害虫</td><td>🔴 彻底改变</td></tr><tr><td>8</td><td><strong>武器系统</strong></td><td>单一条耐久</td><td>头/柄分离、锐利度、武士刀不能磨</td><td>⚠ 影响选装</td></tr><tr><td>9</td><td><strong>职业重做</strong></td><td>固定属性</td><td>木工/NV/老兵增强，新特征</td><td>⚠ 影响开局</td></tr><tr><td>10</td><td><strong>无限荒野</strong></td><td>地图有边界</td><td>边界外程序化生成荒野</td><td>⚠ 影响生存</td></tr></tbody></table><hr><h2 id="对-b41-老玩家的核心提示" tabindex="-1">对 B41 老玩家的核心提示 <a class="header-anchor" href="#对-b41-老玩家的核心提示" aria-label="Permalink to &quot;对 B41 老玩家的核心提示&quot;">​</a></h2><h3 id="你必须改的习惯" tabindex="-1">你必须改的习惯 <a class="header-anchor" href="#你必须改的习惯" aria-label="Permalink to &quot;你必须改的习惯&quot;">​</a></h3><ul><li><strong>拆家具不给木工 XP 了</strong> — 想练木工必须造东西，不是拆东西</li><li><strong>技能书不只是 XP 倍率</strong> — 很多配方<strong>必须读了书才能解锁</strong></li><li><strong>不能无脑抡重武器</strong> — 肌肉疲劳系统让轻型武器有了存在意义</li><li><strong>手电筒必带</strong> — 室内和夜晚现在是真的黑，不是以前那种灰色暗</li><li><strong>武士刀是消耗品了</strong> — B42 不能磨武士刀，坏了就没了</li></ul><h3 id="可以继续用的经验" tabindex="-1">可以继续用的经验 <a class="header-anchor" href="#可以继续用的经验" aria-label="Permalink to &quot;可以继续用的经验&quot;">​</a></h3><ul><li>丧尸基础 AI 没变（依然是视/听觉驱动）</li><li>水电断供机制没变</li><li>车辆系统基本没变</li><li>基础生存机制（饥饿/口渴/体温/伤口）框架没变</li><li>Life and Living 电视节目仍存在，但开局职业起点更高，没那么依赖 TV</li></ul><hr><h2 id="b42-更新时间线" tabindex="-1">B42 更新时间线 <a class="header-anchor" href="#b42-更新时间线" aria-label="Permalink to &quot;B42 更新时间线&quot;">​</a></h2><p>B42 于 <strong>2024 年 12 月</strong> 上线 Steam Unstable 分支，至今仍在持续更新：</p><table tabindex="0"><thead><tr><th>版本</th><th>日期</th><th>关键内容</th></tr></thead><tbody><tr><td>B42.0.0</td><td>2024.12</td><td>初始 Unstable：锻造、动物、地下室、光照、高楼、农业2.0</td></tr><tr><td>B42.14.0</td><td>2026.02</td><td>大量平衡性调整，修复 250+ bug</td></tr><tr><td>B42.16.0</td><td>2026.03</td><td>职业重做、新特征 Tinkerer/Target Shooter、枪支配件 3D 模型</td></tr><tr><td>B42.17.0</td><td>2026.04</td><td>新城镇、职业微调、多人模式修复</td></tr></tbody></table><p><strong>预计稳定版</strong>：目标 2025（已推迟，Unstable 仍在完善中）</p><p><strong>多人模式</strong>：Unstable 初期被禁用，B42.17 开始重新启用</p><p><strong>存档兼容</strong>：B41 存档 ==不兼容== B42，需开新档</p><hr><h2 id="仍在开发中的内容" tabindex="-1">仍在开发中的内容 <a class="header-anchor" href="#仍在开发中的内容" aria-label="Permalink to &quot;仍在开发中的内容&quot;">​</a></h2><p>以下是官方确认但尚未在 Unstable 中实装的功能：</p><table tabindex="0"><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>酿酒 (Brewing)</td><td>即将加入</td></tr><tr><td>玻璃工艺 (Glassmaking)</td><td>部分实装（需稀有工具）</td></tr><tr><td>屠宰 (Butchery)</td><td>即将加入</td></tr><tr><td>弓箭 (Bowyery)</td><td>推迟（需要专门的动画和机制）</td></tr></tbody></table><hr><h2 id="各版块导航" tabindex="-1">各版块导航 <a class="header-anchor" href="#各版块导航" aria-label="Permalink to &quot;各版块导航&quot;">​</a></h2><ul><li><a href="./crafting.html">锻造与制作系统</a> — 6 大新技能 + 制作站链</li><li><a href="./animals.html">畜牧与狩猎</a> — 8 种动物详解</li><li><a href="./farming.html">农业 2.0</a> — 季节系统 + 50+ 作物</li><li><a href="./map.html">新地图与探索</a> — 高楼、地下室、新城镇</li><li><a href="./mechanics.html">新机制详解</a> — 光照、肌肉疲劳、钓鱼、液体系统</li><li><a href="./occupations-tier.html">职业排名</a> — S-D 档 + B42 变化分析</li><li><a href="./weapons-tier.html">近战武器排名</a> — S-D 档 + B42 新机制影响</li></ul>',26)])])}const c=d(n,[["render",l]]);export{u as __pageData,c as default};
